/* ── io com criptografia opcional em repouso ── */
function encBuf(s){ if(!DATA_KEY) return Buffer.from(s,'utf8'); const iv=crypto.randomBytes(12); const c=crypto.createCipheriv('aes-256-gcm',DATA_KEY,iv); const d=Buffer.concat([c.update(s,'utf8'),c.final()]); return Buffer.concat([Buffer.from('VCENC1:'),iv,c.getAuthTag(),d]) }
function decBuf(b){ if(!DATA_KEY) return b.toString('utf8'); if(b.length>47&&b.slice(0,7).toString()==='VCENC1:'){ const iv=b.slice(7,19),tag=b.slice(19,35),d=b.slice(35); const dc=crypto.createDecipheriv('aes-256-gcm',DATA_KEY,iv); dc.setAuthTag(tag); return Buffer.concat([dc.update(d),dc.final()]).toString('utf8') } return b.toString('utf8') }
function writeRaw(f,buf){ fs.mkdirSync(DATA_DIR,{recursive:true}); const t=f+'.tmp'; fs.writeFileSync(t,buf); try{fs.chmodSync(t,0o600)}catch(e){}; fs.renameSync(t,f) }
function loadJson(f,def){ const r=fs.existsSync(f)?fs.readFileSync(f):null; if(!r) return structuredClone(def); try{ return Object.assign(structuredClone(def),JSON.parse(decBuf(r))) }catch(e){ try{ return Object.assign(structuredClone(def),JSON.parse(r.toString('utf8'))) }catch(_){ return structuredClone(def) } } }
function saveJson(f,obj){ writeRaw(f,encBuf(JSON.stringify(obj,null,2))) }
function logAccess(line){ const _ts=new Date().toISOString(); try{ fs.appendFileSync(ACCESS_LOG,_ts+' '+line+'\n') }catch(e){} try{ if(typeof _db!=='undefined'&&_db){ const m=String(line).match(/^(\S+)\s(.*)$/); _db.prepare('insert into audit(ts,ip,ev) values(?,?,?)').run(_ts,m?m[1]:'',m?m[2]:line) } }catch(e){} }

