/* ── banco de dados: SQLite (better-sqlite3) com fallback p/ arquivos JSON ── */
const DBFILE=path.join(DATA_DIR,'vapecloud.db')
let dbEngine='json', _db=null
if((process.env.DB||'auto')!=='json'){ try{ fs.mkdirSync(DATA_DIR,{recursive:true}); const m=await import('better-sqlite3'); const D=m.default||m; _db=new D(DBFILE); _db.pragma('journal_mode=WAL'); _db.pragma('foreign_keys=ON'); _db.exec('CREATE TABLE IF NOT EXISTS kv(key TEXT PRIMARY KEY, value TEXT)'); _db.exec('CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, ip TEXT, ev TEXT)'); dbEngine='sqlite' }catch(e){ dbEngine='json'; _db=null } }
const _kvRead=k=>{ if(dbEngine==='sqlite'&&_db){ const r=_db.prepare('select value from kv where key=?').get(k); return r?Buffer.from(r.value,'base64'):null } const f=path.join(DATA_DIR,k+'.json'); return fs.existsSync(f)?fs.readFileSync(f):null }
const _kvWrite=(k,v)=>{ const buf=encBuf(JSON.stringify(v)); if(dbEngine==='sqlite'&&_db){ _db.prepare('insert into kv(key,value) values(?,?) on conflict(key) do update set value=excluded.value').run(k,buf.toString('base64')) } else { writeRaw(path.join(DATA_DIR,k+'.json'),buf) } }
function dbGet(k,def){ const raw=_kvRead(k); if(raw==null) return structuredClone(def); try{ return Object.assign(structuredClone(def),JSON.parse(decBuf(raw))) }catch(e){ return structuredClone(def) } }
function dbSet(k,v){ _kvWrite(k,v) }
for(const _k of ['store','products','auth','customers']){ try{ if(dbEngine==='sqlite'&&_db&&_kvRead(_k)==null){ const f=path.join(DATA_DIR,_k+'.json'); if(fs.existsSync(f)){ const d=_k==='store'?DEFAULT_STORE:_k==='products'?DEFAULT_PRODUCTS:{}; dbSet(_k,Object.assign(structuredClone(d),JSON.parse(decBuf(fs.readFileSync(f))))) } } }catch(e){} }
