function hashPw(pw,salt){ return crypto.scryptSync(pw,salt,64).toString('hex') }
function userMatches(u,pw){ if(!u)return false; const h=Buffer.from(hashPw(pw||'',u.salt),'hex'); const s=Buffer.from(u.hash,'hex'); return h.length===s.length&&crypto.timingSafeEqual(h,s) }
