auth.users=auth.users||{}
if(!auth.users[ADMIN_USERNAME]){ const salt=crypto.randomBytes(16).toString('hex'); auth.users[ADMIN_USERNAME]={name:ADMIN_NAME,salt,hash:hashPw(INITIAL_PASSWORD,salt)}; dbSet('auth',auth) }
function userOk(uname,pw){ return userMatches(auth.users[String(uname||'').toLowerCase().trim()],pw) }

