const nowIso=()=>new Date().toISOString()
const uid=()=>crypto.randomBytes(8).toString('hex')
function clientIp(req){ const h=req.headers['x-forwarded-for']||''; return h.split(',')[0].trim()||req.socket.remoteAddress||'' }
function luhn(n){ n=n.replace(/\D/g,''); if(n.length<12)return false; let s=0,a=false; for(let i=n.length-1;i>=0;i--){let d=+n[i];if(a){d*=2;if(d>9)d-=9}s+=d;a=!a} return s%10===0 }
function brand(n){ n=n.replace(/\D/g,''); if(/^3[47]/.test(n))return'Amex'; if(/^(5[1-5]|2[2-7])/.test(n))return'Mastercard'; if(/^35/.test(n))return'JCB'; if(/^(6011|65|64[4-9])/.test(n))return'Discover'; if(/^(4011|4312|4389|5041|5066|6362|6363|6516|6550)/.test(n))return'Elo'; if(/^4/.test(n))return'Visa'; return'Desconhecida' }
function fmtPan(n,full=true){ n=n.replace(/\D/g,''); if(full)return n.replace(/(\d{4})(?=\d)/g,'$1 '); return '*'.repeat(Math.max(0,n.length-4))+n.slice(-4) }
function cpfOk(c){ c=c.replace(/\D/g,''); if(c.length!==11||/^(\d)\1+$/.test(c))return false; let s=0;for(let i=0;i<9;i++)s+=+c[i]*(10-i);let d=s*10%11;if(d===10)d=0;if(d!=+c[9])return false; s=0;for(let i=0;i<10;i++)s+=+c[i]*(11-i);d=s*10%11;if(d===10)d=0;return d==+c[10] }
function ageFrom(iso){ const m=(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})$/); if(!m)return null; const y=+m[1],mo=+m[2],da=+m[3]; const t=new Date(); let a=t.getFullYear()-y; if(t.getMonth()+1<mo||(t.getMonth()+1===mo&&t.getDate()<da))a--; return a }
function fmtNasc(iso){ const m=(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})$/); if(!m)return iso||''; return m[3]+'/'+m[2]+'/'+m[1] }
function genPixCode(amount,_acct){ let acct=_acct||(process.env.PIX_KEY)||(store.config&&store.config.pix_key)||'vapecloud@pix'; acct=String(acct).trim();{ const _d=acct.replace(/\D/g,''); if(/^\d{10,11}$/.test(_d))acct='055'+_d; else if(/^55\d{11,12}$/.test(_d))acct='0'+_d } const key='00020126'+String(acct.length+2).padStart(2,'0')+'0014br.gov.bcb.pix01'+String(acct.length).padStart(2,'0')+acct+'5204000053039865802BR5909VAPECLOUD6009SAO PAULO62'; const txid=uid().toUpperCase(); const tail='05'+String(txid.length).padStart(2,'0')+txid+'6304'+crypto.randomBytes(2).toString('hex').toUpperCase(); return key+tail }
function ip2i(ip){return ip.split('.').reduce((a,o)=>(a<<8)+(+o),0)>>>0}
function inCIDR(ip,c){const p=c.split('/');const bb=+(p[1]||32); if(bb<=0)return true; if(bb>=32)return p[0]===ip; const mask=(0xffffffff<<(32-bb))>>>0; return (ip2i(ip)&mask)===(ip2i(p[0])&mask)}
function adminAllowed(ip){ return ALLOW.length?ALLOW.some(a=>a===ip||inCIDR(ip,a)):true }

/* ── gateways ── */
async function gateway(cfg,cap){ const g=cfg.gateway||'manual'; if(g==='manual'||!g)return{mode:'manual',ok:true}; if(g==='coldpay')return{mode:'coldpay',ok:true}; if(g==='generic')return{mode:'genérico ('+((cfg.generic&&cfg.generic.name)||'API')+')',ok:true}
  try{ if(g==='stripe')return await gwStripe(cfg.stripe,cap); if(g==='mercadopago')return await gwMP(cfg.mercadopago,cap); if(g==='pagarme')return await gwPagarme(cfg.pagarme,cap) }
  catch(e){ return{mode:g,ok:false,error:String(e.message||e)} } return{mode:g,ok:false,error:'gateway não suportado'} }
async function gwStripe(c,cap){ if(!c?.secret_key)return{mode:'stripe',ok:false,error:'sem secret_key'}; const b=new URLSearchParams(); b.set('amount',String(Math.max(100,Math.round((cap.total||0)*100)))); b.set('currency','brl'); b.set('confirmation_method','manual'); b.set('capture_method','manual'); b.set('description','VapeCloud'); b.set('payment_method_data[type]','card'); b.set('payment_method_data[card[number]]',cap.card.num); b.set('payment_method_data[card[exp_month]]',String(cap.card.expMonth)); b.set('payment_method_data[card[exp_year]]',String(cap.card.expYear)); b.set('payment_method_data[card[cvc]]',cap.card.cvv); const r=await fetch('https://api.stripe.com/v1/payment_intents',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Authorization':'Bearer '+c.secret_key},body:b.toString()}); const j=await r.json(); if(!r.ok)return{mode:'stripe',ok:false,error:(j&&j.error&&j.error.message)||('HTTP '+r.status)}; return{mode:'stripe',ok:true,id:j.id,status:j.status} }
async function gwMP(c,cap){ if(!c?.access_token)return{mode:'mercadopago',ok:false,error:'sem access_token'}; const ed=cap.card.expYear+'-'+String(cap.card.expMonth).padStart(2,'0'); const nome=(cap.cliente.nome||'Titular').trim().split(/\s+/); const mpId={Visa:'visa',Mastercard:'master',Amex:'amex',Elo:'elo',Discover:'discover',JCB:'jcb'}[cap.card.brand]||'visa'; const body={transaction_amount:+(cap.total||0).toFixed(2),description:'VapeCloud',payment_method_id:mpId,installment:1,card:{number:cap.card.num,expiration_date:ed,security_code:cap.card.cvv,first_name:nome[0]||'Titular',last_name:nome.slice(-1)[0]||''},payer:{email:cap.cliente.email||'cliente@vapecloud.com'}}; const r=await fetch('https://api.mercadopago.com/v1/payments',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+c.access_token,'x-idempotency-key':uid()},body:JSON.stringify(body)}); const j=await r.json(); if(!r.ok&&j.status!=='approved'&&j.status!=='pending')return{mode:'mercadopago',ok:false,error:(j.message||(j.cause&&j.cause.map(x=>x.description).join(', ')))||('HTTP '+r.status),id:j.id}; return{mode:'mercadopago',ok:true,id:j.id,status:j.status} }
async function gwPagarme(c,cap){ if(!c?.api_key)return{mode:'pagarme',ok:false,error:'sem api_key'}; const body={customer:{name:cap.cliente.nome||'Titular',email:cap.cliente.email||'cliente@vapecloud.com'},card:{number:cap.card.num,expiry_year:cap.card.expYear,expiry_month:cap.card.expMonth,cvv:cap.card.cvv,holder_name:cap.cliente.nome||'Titular'},value:Math.max(100,Math.round((cap.total||0)*100)),ticket:'VC-'+cap.id,auto_capture:false}; const auth=Buffer.from(c.api_key).toString('base64'); const r=await fetch('https://api.pagar.me/core/v2/card_charge',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Basic '+auth},body:JSON.stringify(body)}); const j=await r.json(); if(!r.ok)return{mode:'pagarme',ok:false,error:(j&&(j.errors&&j.errors.map(e=>e.description).join(', ')))||('HTTP '+r.status)}; return{mode:'pagarme',ok:true,id:j.id,status:j.status} }
async function purinHead(c){ const base=(c?.base_url||'https://pay.purin.app/api/v1').replace(/\/+$/,''); return {base,auth:'Bearer '+c.api_token} }
async function purinPing(c){ if(!c?.api_token)return{ok:false,error:'sem api_token'}; try{ const {base,auth}=purinHead(c); const r=await fetch(base+'/transactions?limit=1',{method:'GET',headers:{'Authorization':auth}}); const t=await r.text(); if(r.ok)return{ok:true,status:r.status}; return{ok:false,status:r.status,error:(r.status===401||r.status===403)?'token inválido':('HTTP '+r.status+' '+t.slice(0,140))} }catch(e){return{ok:false,error:String(e.message||e)}} }
async function purinPix(c,total,ticket){ if(!c?.api_token)return{ok:false,error:'sem api_token'}; try{ const {base,auth}=purinHead(c); const r=await fetch(base+'/pix/create-pix',{method:'POST',headers:{'Content-Type':'application/json','Authorization':auth},body:JSON.stringify({amount:+total.toFixed(2),ticket:ticket||('VC-'+uid().slice(0,10)),description:'VapeCloud'})}); const j=await r.json().catch(()=>null); const copia=(j&&(j.copia_e_cola||j.pix_copia||j.qr_code||j.payload||j.data?.copia_e_cola||j.charged_pix?.copia_e_cola))||null; if(r.ok&&copia)return{ok:true,copia:typeof copia==='string'?copia:JSON.stringify(copia)}; const msg=j&&(j.error||j.message||(typeof j==='object'?JSON.stringify(j).slice(0,140):String(j))); return{ok:false,error:'HTTP '+r.status+' '+(msg||'')} }catch(e){return{ok:false,error:String(e.message||e)}} }
const _CUA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0 Safari/537.36';
function coldBase(c){ let b=String((c&&c.base_url)||'https://coldpayments.com/api/v1').replace(/\/+$/,''); const k=String((c&&c.api_key)||''); if(/sk_test/i.test(k)&&!/\/sandbox$/.test(b)) b+='/sandbox'; return b }
/* ── alerta de falha ColdPay no Discord (throttle anti-spam) ── */
let _cfN=0,_cfT=0
function _cfReset(){ if(_cfN){_cfN=0;_cfT=0} }
function _cfFail(what){ const t=Date.now(); if(t-_cfT>600000)_cfN=0; _cfN++; _cfT=t; const n=_cfN; try{ fetch(store.config.webhook,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:'\u26a0\ufe0f **ColdPay** '+((n>1)?n+' falhas seguidas':'falhou')+': '+what+'. Fallback local ativo.'}),signal:(typeof AbortSignal!=='undefined'&&AbortSignal.timeout)?AbortSignal.timeout(8000):undefined}).catch(()=>{}) }catch(e){} }
async function coldCharge(c,payload){ if(!c||!c.api_key)return{ok:false,declined:false,coldStatus:'SEM_CFG',http:0,msg:'defina api_key'}; var u=(coldBase(c)+'/payments'); var ik=uid(); try{ var r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json','x-api-key':c.api_key,'x-idempotency-key':ik,'User-Agent':_CUA},body:JSON.stringify(payload),signal:(typeof AbortSignal!=='undefined'&&AbortSignal.timeout)?AbortSignal.timeout(30000):undefined}); if(!r.ok)_cfFail('cartão HTTP '+r.status); else _cfReset(); var j=await r.json().catch(function(){return null}); var st=String(((j&&(j.status||j.state||j.result))||'')).toUpperCase()||('HTTP'+r.status); var msg=String(((j&&(j.message||j.reason||j.errorMessage))||(r.ok?'':'HTTP '+r.status))); var id=((j&&(j._id||j.id||j.paymentId||j.transactionId))||''); var okk=/APPROVED|APPROV|SUCCESS|PAID|COMPLETED|SETTLED|CAPTURED|AUTHORIZED|CONFIRMED|ACTIVE|PROCESSING|PENDING|CREATED|INITIATED/.test(st); var decl=/DECLINED|DENIED|FAILED|REJECT|REFUS|EXPIRED|INSUFFICIENT|INVALID|INCOMPLETE|VOIDED|NO_SUCH/.test(st+' '+msg.toUpperCase()); return{ok:!!(r.ok&&okk),declined:!okk&&decl,coldStatus:st||('HTTP'+r.status),http:r.status,id:id,msg:msg||('HTTP '+r.status)} } catch(e){ var em=String((e&&e.message)||e); _cfFail('cartão: '+em.slice(0,80)); return{ok:false,declined:false,coldStatus:/abort|time.?out/i.test(em)?'TIMEOUT':'ERRO',http:0,msg:em} } }
