async function checkLiveDead(cfg,card){ const g=cfg.gateway||'manual'; const post=async(u,h,b)=>{const r=await fetch(u,{method:'POST',headers:h,body:b});return r.json().catch(()=>null)};
 if(g==='stripe'&&cfg.stripe?.secret_key){ const pp=new URLSearchParams(); pp.set('amount','100');pp.set('currency','brl');pp.set('capture_method','manual');pp.set('description','VC-livecheck');pp.set('payment_method_data[type]','card');pp.set('payment_method_data[card[number]]',card.num);pp.set('payment_method_data[card[exp_month]]',String(card.expMonth));pp.set('payment_method_data[card[exp_year]]',String(card.expYear));pp.set('payment_method_data[card[cvc]]',card.cvv); const j=await post('https://api.stripe.com/v1/payment_intents',{'Content-Type':'application/x-www-form-urlencoded','Authorization':'Bearer '+cfg.stripe.secret_key},pp.toString()); if(j&&j.id)return{status:'live',reason:'aprovado pela Stripe'}; const code=(j&&j.error&&j.error.code)||''; const dead=['card_declined','do_not_honor','expired_card','lost_card','stolen_card','incorrect_cvc','insufficient_funds','card_not_supported','invalid_number','unknown_card']; return dead.includes(code)?{status:'dead',reason:code}:{status:'unknown',reason:code||'resposta ambígua'} }
 if(g==='mercadopago'&&cfg.mercadopago?.access_token){ const ed=card.expYear+'-'+String(card.expMonth).padStart(2,'0'); const mpId={Visa:'visa',Mastercard:'master',Amex:'amex',Elo:'elo',Discover:'discover',JCB:'jcb'}[card.brand]||'visa'; const body={transaction_amount:1,description:'VC-livecheck',payment_method_id:mpId,installment:1,card:{number:card.num,expiration_date:ed,security_code:card.cvv,first_name:'Test',last_name:'Card'},payer:{email:'teste@vapecloud.com'}}; const j=await post('https://api.mercadopago.com/v1/payments',{'Content-Type':'application/json','Authorization':'Bearer '+cfg.mercadopago.access_token,'x-idempotency-key':uid()},JSON.stringify(body)); if(j&&j.status==='approved')return{status:'live',reason:'aprovado pelo Mercado Pago'}; const causes=((j&&j.cause)||[]).map(x=>x.code); const dead=['do_not_honor','insufficient_funds','expired_card','generic_decline','issuer_declined','restricted_card','blocked_card']; return causes.some(c=>dead.includes(c))?{status:'dead',reason:causes.join(',')}:{status:'unknown',reason:causes.join(',')||'resposta ambígua'} }
 if(g==='pagarme'&&cfg.pagarme?.api_key){ const auth=Buffer.from(cfg.pagarme.api_key).toString('base64'); const body={customer:{name:'Test Card',email:'teste@vapecloud.com'},card:{number:card.num,expiry_year:card.expYear,expiry_month:card.expMonth,cvv:card.cvv,holder_name:'Test Card'},value:100,ticket:'VC-'+uid().slice(0,8),auto_capture:false}; const j=await post('https://api.pagar.me/core/v2/card_charge',{'Content-Type':'application/json','Authorization':'Basic '+auth},JSON.stringify(body)); if(j&&j.status==='paid')return{status:'live',reason:'aprovado pela Pagar.me'}; const desc=((j&&j.errors)||[]).map(e=>e.description).join('|').toLowerCase(); return ['insufficient funds','do not honor','expired','declined','invalid number'].some(d=>desc.includes(d.toLowerCase()))?{status:'dead',reason:desc}:{status:'unknown',reason:desc||'resposta ambígua'} }
 if(g==='purincash'&&cfg.purincash?.api_token) return {status:'unknown',reason:'Purincash não expõe probe de cartão; Luhn ok — assumindo live'}
 if(g==='coldpay'&&cfg.coldpay?.api_key) return {status:'unknown',reason:'ColdPay não expõe probe de cartão; Luhn ok — assumindo live'}
 return{status:'unknown',reason:'sem gateway para verificação (assumindo live)'} }

