const custSessions={}; try{ Object.assign(custSessions, dbGet('cust_sessions',{})) }catch(e){} function _ssSave(){ try{ dbSet('cust_sessions',custSessions) }catch(e){} }
function custCookieVal(sid){ return 'vc_cust='+sign(sid)+'; HttpOnly; SameSite=Lax'+(SECURE?'; Secure':'')+'; Path=/; Max-Age='+CUST_SESSION_DAYS*86400 }
function clearCustCookie(res){ res.setHeader('Set-Cookie','vc_cust=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0') }
function currentCust(req){ const v=getCookies(req).vc_cust; if(!v)return null; const sid=unsign(v); if(!sid)return null; const s=custSessions[sid]; if(!s)return null; if(Date.now()-s.iat>CUST_SESSION_DAYS*86400*1000){ try{delete custSessions[sid];dbSet('cust_sessions',custSessions)}catch(e){} return null } return {sid,email:s.email} }
function requireCust(req,res,next){ const s=currentCust(req); if(!s)return res.status(401).json({ok:false,unauthorized:true}); res.locals.cust=s; next() }

