const app=express(); app.disable('x-powered-by'); app.set('trust proxy',true)
app.use(express.json({limit:'64kb'}))
app.use((req,res,next)=>{ res.setHeader('X-Content-Type-Options','nosniff'); res.setHeader('X-Frame-Options','DENY'); res.setHeader('Referrer-Policy','strict-origin-when-cross-origin'); res.setHeader('Permissions-Policy','camera=(),geolocation=(),microphone=()'); res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com data:; img-src 'self' data: https://api.qrserver.com; connect-src 'self' https://api.qrserver.com https://viacep.com.br; frame-ancestors 'none'; base-uri 'self'"); if(SECURE)res.setHeader('Strict-Transport-Security','max-age=31536000; includeSubDomains'); const _hp=req.originalUrl.split('?')[0]; if(_hp===ADMIN_PATH||_hp.startsWith('/'+ADMIN_PATH.slice(1)))res.setHeader('Cache-Control','no-store'); else if(_hp==='/'||/\.html?$/.test(_hp))res.setHeader('Cache-Control','no-cache'); next() })
app.use((req,res,next)=>{ res.locals.side=(SPLIT&&req.socket&&req.socket.localPort===ADMIN_PORT)?'admin':'store'; next() })
app.use((req,res,next)=>{ const p=req.path,ap=ADMIN_PATH; const isA=(p===ap)||(p==='/'+ap.slice(1))||(p.startsWith('/'+ap.slice(1)+'/'))||(p.indexOf('admin.html')!==-1)||(p.startsWith('/api/admin')); if(res.locals.side==='admin'){ const keep=(p==='/')||isA||/^(\/favicon\.ico)$/.test(p)||/\.(ico|svg|png|jpe?g|gif|css|js|woff2?)$/i.test(p); if(!keep)return res.status(404).send('not found') } else if(SPLIT){ if(isA)return res.status(404).send('not found') } next() })
app.get('/',(req,res,next)=>{ if(res.locals.side==='admin')return res.sendFile(path.join(__dirname,'public','admin.html')); next() })
function slugify(s){ return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'') }
app.get('/produto/:slug',(req,res)=>{ const s=String(req.params.slug||'').toLowerCase(); const hit=products.filter(p=>p.active).find(p=>slugify(p.name)===s||String(p.id)===s); res.sendFile(path.join(__dirname,'public',hit?'produto.html':'index.html')) })
