/* ── 2FA · TOTP nativo ─────────────────────────────── */
const _B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
function b32enc(buf){ let bits=0,val=0,out=''; for(const b of buf){ val=(val<<8)|b; bits+=8; while(bits>=5){ out+=_B32[(val>>>(bits-5))&31]; bits-=5 } } if(bits>0)out+=_B32[(val<<(5-bits))&31]; return out }
function b32dec(str){ str=String(str||'').toUpperCase().replace(/[^A-Z2-7]/g,''); let bits=0,val=0; const out=[]; for(const ch of str){ const ix=_B32.indexOf(ch); if(ix<0)continue; val=(val<<5)|ix; bits+=5; if(bits>=8){ out.push((val>>>(bits-8))&255); bits-=8 } } return Buffer.from(out) }
function totpGen(secretBuf,off){ const t=Math.floor(Date.now()/30000)+ (off||0); const buf=Buffer.alloc(8); buf.writeBigUInt64BE(BigInt(t)); const h=crypto.createHmac('sha1',secretBuf).update(buf).digest(); const o=h[19]&15; const v=((h[o]&0x7f)<<24)|(h[o+1]<<16)|(h[o+2]<<8)|h[o+3]; return String(v%1000000).padStart(6,'0') }
function totpOk(secretB32,code){ const sb=b32dec(secretB32); if(!sb.length)return false; code=String(code||'').replace(/\D/g,''); if(code.length!==6)return false; for(let w=-1;w<=1;w++){ const g=totpGen(sb,w); if(g.length===code.length&&crypto.timingSafeEqual(Buffer.from(g),Buffer.from(code)))return true } return false }
function _totpOn(){ return !!(store.config.security&&store.config.security.totp) }
const _pend2fa=new Map(); setInterval(()=>{const t=Date.now();for(const[k,v]of _pend2fa)if(t-v.t0>10*60e3)_pend2fa.delete(k)},60000).unref()
function _mkAdmin(res,uname){ const u=auth.users[uname]||{}; const sid=uid()+uid(); const csrf=sign(uid()); sessions[sid]={iat:Date.now(),csrf,user:{name:u.name,uname}}; res.setHeader('Set-Cookie',cookieVal(sid)); return {ok:true,csrf:csrf,name:u.name,uname} }
app.get('/api/admin/state',requireAdmin,(req,res)=>res.json({ok:true,adminPath:ADMIN_PATH,name:(res.locals.session.user||{}).name,uname:(res.locals.session.user||{}).uname}))
app.post('/api/admin/login',async(req,res)=>{ const ip=clientIp(req); const r=rate(ip,8,10*60*1000,5); if(!r.ok){ logAccess(ip+' LOGIN-BLOCKED'); return res.status(429).json({ok:false,error:r.code==='locked'?'Muitas tentativas. Aguarde alguns minutos.':'Muitas requisições. Tente em instantes.'}) }
  const uname=String(req.body?.username||ADMIN_USERNAME).toLowerCase().trim(); const pw=req.body?.password||''; const u=auth.users[uname]; let okPw=false; if(u){ okPw=userMatches(u,pw) } else { hashPw(pw||'','deadbeefdeadbeef') }
  const nf=((rl[ip]&&rl[ip].fails)||[]).filter(x=>Date.now()-x<10*60*1000).length; if(nf>=2&&!okPw)await new Promise(z=>setTimeout(z,250*nf));
  if(okPw){ if(_totpOn()){ const tk=uid()+uid(); _pend2fa.set(tk,{uname,ip,t0:Date.now(),tries:0,last:0}); logAccess(ip+' LOGIN-2FA'); return res.json({ok:true,step:'totp',ticket:tk}) } logAccess(ip+' LOGIN-OK user='+uname); return res.json(_mkAdmin(res,uname)) }
  noteFail(ip); logAccess(ip+' LOGIN-FAIL user='+(uname||'?')); res.status(401).json({ok:false,error:'Usuário ou senha incorretos.'}) })
app.post('/api/admin/2fa',(req,res)=>{ const ip=clientIp(req); const r=rate(ip,12,10*60*1000,8); if(!r.ok)return res.status(429).json({ok:false,error:'Muitas tentativas. Aguarde alguns minutos.'}); const tk=String((req.body||{}).ticket||''); const code=String((req.body||{}).code||'').replace(/\D/g,''); const p=_pend2fa.get(tk); if(!p||p.ip!==ip||Date.now()-p.t0>10*60e3)return res.status(401).json({ok:false,error:'Sessão expirou. Entre novamente.'}); if(p.last&&Date.now()-p.last<4000)return res.status(429).json({ok:false,error:'Aguarde alguns segundos e tente de novo.'}); p.last=Date.now(); const sec=store.config.security&&store.config.security.totp; if(sec&&totpOk(sec,code)){ _pend2fa.delete(tk); logAccess(ip+' 2FA-OK'); return res.json(_mkAdmin(res,p.uname)) } p.tries++; noteFail(ip); if(p.tries>=8)_pend2fa.delete(tk); logAccess(ip+' 2FA-FAIL'); res.status(401).json({ok:false,error:p.tries>=8?'Tentativas esgotadas. Entre novamente.':'Código incorreto.'}) })
app.post('/api/admin/totp-setup',requireAdmin,requireCsrf,(req,res)=>{ const sec=b32enc(crypto.randomBytes(20)); store.config.security=Object.assign({},store.config.security,{prelim:sec}); dbSet('store',store); const uri='otpauth://totp/'+encodeURIComponent(((store.config.security.label||'VapeCloud')+' Admin').trim())+'?secret='+sec+'&issuer=VapeCloud&algorithm=SHA1&digits=6&period=30'; res.json({ok:true,secret:sec,uri}) })
app.post('/api/admin/totp-enable',requireAdmin,requireCsrf,(req,res)=>{ const b=store.config.security||{}; if(!b.prelim)return res.json({ok:false,error:'Gere primeiro o código de verificação.'}); if(!totpOk(b.prelim,String((req.body||{}).code||''))){return res.json({ok:false,error:'Código incorreto — confira seu app de autenticação e tente de novo.'})} store.config.security=Object.assign({},b,{totp:b.prelim,prelim:''}); dbSet('store',store); logAccess(clientIp(req)+' TOTP-ON'); res.json({ok:true}) })
app.post('/api/admin/totp-disable',requireAdmin,requireCsrf,(req,res)=>{ const b=store.config.security||{}; if(!b.totp)return res.json({ok:false,error:'2FA não está ativo.'}); if(!totpOk(b.totp,String((req.body||{}).code||''))){return res.json({ok:false,error:'Código incorreto.'})} store.config.security=Object.assign({},b,{totp:'',prelim:''}); dbSet('store',store); logAccess(clientIp(req)+' TOTP-OFF'); res.json({ok:true}) })
