app.post('/api/admin/users',requireAdmin,requireCsrf,(req,res)=>{ const name=String((req.body||{}).name||'').trim().slice(0,40); const un=String((req.body||{}).username||'').trim().toLowerCase().replace(/\s+/g,''); if(name.length<2)return res.status(400).json({ok:false,error:'Informe o nome.'}); if(!/^[a-z0-9._-]{3,20}$/.test(un))return res.status(400).json({ok:false,error:'Username inválido (3-20; letras, números, . _ -)'}); if(auth.users[un])return res.status(409).json({ok:false,error:'Já existe esse usuário.'}); const temp=crypto.randomBytes(6).toString('base64url'); const salt=crypto.randomBytes(16).toString('hex'); auth.users[un]={name,salt,hash:hashPw(temp,salt)}; dbSet('auth',auth); logAccess(clientIp(req)+' USER-CREATE '+un+' by '+actor(res)); res.json({ok:true,username:un,tempPassword:temp}) })
app.patch('/api/admin/users/:un',requireAdmin,requireCsrf,(req,res)=>{ const un=String(req.params.un).toLowerCase(); const u=auth.users[un]; if(!u)return res.status(404).json({ok:false,error:'Usuário não encontrado.'}); const b=req.body||{}; if(b.name!=null)u.name=String(b.name).trim().slice(0,40)||u.name; if(b.password){ const pw=String(b.password); if(pw.length<6)return res.status(400).json({ok:false,error:'Senha muito curta.'}); u.salt=crypto.randomBytes(16).toString('hex'); u.hash=hashPw(pw,u.salt) } dbSet('auth',auth); logAccess(clientIp(req)+' USER-UPDATE '+un+' by '+actor(res)); res.json({ok:true}) })
app.delete('/api/admin/users/:un',requireAdmin,requireCsrf,(req,res)=>{ const un=String(req.params.un).toLowerCase(); if(!auth.users[un])return res.status(404).json({ok:false}); if(Object.keys(auth.users).length<=1)return res.status(400).json({ok:false,error:'É preciso manter ao menos um usuário.'}); if(un===res.locals.session.user.uname)return res.status(400).json({ok:false,error:'Você não pode excluir a si mesmo.'}); delete auth.users[un]; dbSet('auth',auth); logAccess(clientIp(req)+' USER-DELETE '+un+' by '+actor(res)); res.json({ok:true}) })
