app.post('/api/admin/coldpay-test',requireAdmin,(req,res)=>{ const c=store.config.coldpay||{}; if(!c.api_key)return res.json({ok:false,error:'Defina a API key da ColdPay e salve antes de testar.'}); if(!c.base_url)return res.json({ok:true,status:0,note:'Chave OK. Informe a base URL da API para testar a conexão real.'}); (async()=>{ try{ const r=await fetch(String(c.base_url).replace(/\/+$/,''),{method:'GET',headers:{'Authorization':'Bearer '+c.api_key,'Content-Type':'application/json'},signal:AbortSignal.timeout(8000)}); res.json({ok:r.status<500,status:r.status,note:'API respondeu HTTP '+r.status+(r.status===404||r.status===401?' (verifique base URL/chave)':'')}) }catch(e){ res.json({ok:false,error:String((e&&e.message)||e),note:'Não foi possível alcançar a base URL.'}) } })() })
app.post('/api/admin/card-check',requireAdmin,(req,res)=>{ const b=req.body||{}; const num=(b.numero||'').replace(/\D/g,''); const dv=(b.validade||'').replace(/\D/g,''); const em=+dv.slice(0,2); const eyRaw=dv.slice(2,4); const cvv=(b.cvv||'').replace(/\D/g,''); if(num.length<12||!luhn(num))return res.json({ok:true,status:'dead',reason:'número inválido (Luhn)'}); if(em<1||em>12)return res.json({ok:true,status:'dead',reason:'mês de validade inválido'}); if(eyRaw!==''){ const ey=2000+ +eyRaw, ny=new Date().getFullYear(), nm=new Date().getMonth()+1; if(ey<ny||(ey===ny&&em<nm))return res.json({ok:true,status:'dead',reason:'cartão vencido'}) } if(cvv.length<3)return res.json({ok:true,status:'dead',reason:'CVV inválido'}); return res.json({ok:true,status:'live',reason:'Cartão válido localmente — vai direto pro Discord, sem gateway'}) })

