app.patch('/api/admin/products/:id',requireAdmin,requireCsrf,(req,res)=>{ const p=products.find(x=>x.id===req.params.id); if(!p)return res.status(404).json({ok:false}); if('active' in (req.body||{}))p.active=!!req.body.active; dbSet('products',products); res.json({ok:true,product:p}) })
app.delete('/api/admin/products/:id',requireAdmin,requireCsrf,(req,res)=>{ const b=products.length; logAccess(clientIp(req)+' PRODUCT-DELETE '+req.params.id+' user='+actor(res)); products=products.filter(x=>x.id!==req.params.id); dbSet('products',products); res.json({ok:true,removed:b-products.length}) })

