function tailLog(n){ try{ if(!fs.existsSync(ACCESS_LOG))return []; return fs.readFileSync(ACCESS_LOG,'utf8').trim().split('\n').slice(-n).map(x=>{ const m=x.match(/^(\S+)\s(\S+)\s(.*)$/); if(m) return {ts:m[1],ip:m[2],ev:m[3]}; const m2=x.match(/^(\S+) (.*)$/); return {ts:m2?m2[1]:'',ev:m2?m2[2]:x} }) }catch(e){ return [] } }
app.get('/api/admin/activity',requireAdmin,(req,res)=>{ const n=Math.min(Number(req.query.n)||200,1000); let lines=tailLog(n); if(_db){ lines=_db.prepare('select ts,ip,ev from audit order by id desc limit ?').all(n).map(r=>({ts:r.ts,ip:r.ip,ev:r.ev})) } res.json({ok:true,lines}) })
