app.post('/api/admin/gw-test',requireAdmin,(req,res)=>{ const c=store.config.coldpay||{}; if(!c.api_key)return res.json({ok:false,gw:'coldpay',error:'Defina a API key da ColdPay e salve antes de testar.'}); if(!c.base_url)return res.json({ok:true,gw:'coldpay',note:'Chave OK. Informe a base URL da API para testar a conexão real.'}); (async()=>{ try{ const r=await fetch(String(c.base_url).replace(/\/+$/,''),{method:'GET',headers:{'x-api-key':c.api_key,'Content-Type':'application/json'},signal:AbortSignal.timeout(8000)}); res.json({ok:r.status<500,gw:'coldpay',status:r.status,note:'API respondeu HTTP '+r.status+' — ColdPay é usada só para gerar PIX.'}) }catch(e){ res.json({ok:false,gw:'coldpay',error:String(e.message||e)}) } })() })
app.patch('/api/admin/captures/:id/status',requireAdmin,requireCsrf,(req,res)=>{ const c=store.captures.find(x=>x.id===req.params.id||String(x.seq)===String(req.params.id)); if(!c)return res.status(404).json({ok:false,error:'não encontrado'}); const st=String((req.body||{}).status||''); if(!['aprovado','confirmado','em_preparo','enviado','entregue','recusado','menor'].includes(st))return res.status(400).json({ok:false,error:'status inválido'}); const _pixPrev=(c.tipo==='pix'&&c.status!=='aprovado'&&st==='aprovado'); c.status=st; c.statusHist=c.statusHist||[]; c.statusHist.push({s:st,t:nowIso()}); if(_pixPrev){ try{ notifyPixPaid(c,'admin'); dbSet('store',store) }catch(e){} } dbSet('store',store); logAccess(clientIp(req)+' STATUS='+st+' #'+c.seq+' user='+actor(res)); res.json({ok:true}) })
app.get('/api/track',(req,res)=>{ const ip=clientIp(req); const r=rate(ip,90,10*60*1000,25); if(!r.ok)return res.status(429).json({ok:false,error:'Muitas consultas. Aguarde um pouco.'}); const n=String(req.query.n||req.query.pedido||'').trim(); if(!(/^[0-9]{1,6}$/.test(n)||/^[a-z0-9]{16}$/i.test(n)))return res.status(404).json({ok:false,error:'Pedido não encontrado. Confira o número.'}); const c=store.captures.find(x=>String(x.seq)===n||(x.id&&String(x.id)===n)); if(!c)return res.status(404).json({ok:false,error:'Pedido não encontrado. Confira o número.'}); const st=c.status||'aprovado'; const MAXD=Number(process.env.VC_TRACK_DAYS||7); const days=Math.floor((Date.now()-c.ts)/864e5); const tl=[{k:'Pedido confirmado',d:st!=='pendente'},{k:'Separando seu pedido',d:st!=='pendente'&&days>=1},{k:'Enviado para entrega',d:st!=='pendente'&&days>=2},{k:'Entregue',d:st!=='pendente'&&days>=MAXD}]; const e=c.cliente?.endereco||{}; res.json({ok:true,numero:c.seq,status:st,pendente:st==='pendente',criado:c.ts,quando:new Date(c.ts).toLocaleDateString('pt-BR'),prevEntrega:new Date(c.ts+MAXD*864e5).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'}),itens:(c.pedido?.itens||[]).map(i=>({nome:i.nome,qtd:i.qty})),cidade:(c.cliente&&c.cliente.endereco&&c.cliente.endereco.cidade)||'',uf:(c.cliente&&c.cliente.endereco&&c.cliente.endereco.uf)||'',total:c.total,timeline:tl}) })
async function sendOrderMail(cfg,cap){ try{ const em=cfg.email||{}; if(!em.api_key)return; const items=(cap.pedido?.itens||[]).map(i=>(i.qty||1)+'x '+(i.nome||'')).join('\n')||'—'; const msg='Olá '+(cap.cliente.nome||'')+'\n\nSeu pedido #'+cap.seq+' foi confirmado na VapeCloud.\n\n'+items+'\n\nTotal: R$ '+Number(cap.total).toFixed(2)+'\n\nAcompanhe em: https://SEU-DOMINIO/rastreio.html?n='+cap.seq+'\n\nObrigado! Equipe VapeCloud'; await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+em.api_key},body:JSON.stringify({from:em.from||'VapeCloud <onboarding@resend.dev>',to:[cap.cliente.email].concat(em.to_notify?[em.to_notify]:[]),subject:'Pedido #'+cap.seq+' confirmado — VapeCloud',html:'<p>'+msg.replace(/\n/g,'<br>')+'</p>'})}) }catch(e){} }
